// Creature art. Creatures without art show their emoji instead.
//
// Every pet has pixel art generated by scripts/pixel-pets/generate.mjs (npm run pets), listed in
// pixelPetArt.ts. To replace one with hand-made art: save a square PNG with a transparent background as
// assets/pets/<id>.png (and optionally an eyes-closed assets/pets/<id>-blink.png), then add it to
// HAND_MADE below. The id is the creature's id in catalog.ts (e.g. 'lobster', 'mit_beaver').
//
//   mit_beaver: { base: require('../../assets/pets/mit_beaver.png'), blink: require('../../assets/pets/mit_beaver-blink.png') },
import type { ImageSourcePropType } from 'react-native';
import { PIXEL_PET_ART } from './pixelPetArt';

/** `silhouette`: the pet's shape in translucent black, shown until it's found. Without one, a "?" shows instead. */
export type PetArt = { base: ImageSourcePropType; blink?: ImageSourcePropType; silhouette?: ImageSourcePropType };

/** Hand-made art. Overrides the generated pixel art for the same id. */
const HAND_MADE: Partial<Record<string, PetArt>> = {};

export const PET_ART: Partial<Record<string, PetArt>> = { ...PIXEL_PET_ART, ...HAND_MADE };
